package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class NativeRewardsEntryHelperWiringTest {
 String source()throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/NativeRewardsEntryHelper.java"));}
 @Test public void exactFlagsNoBypass()throws Exception{String s=source();for(String x:new String[]{"FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES","FLAG_REPORT_VIEW_IDS","FLAG_RETRIEVE_INTERACTIVE_WINDOWS","confirmed.flags!=flags"})assertTrue(s.contains(x));for(String x:new String[]{"getWindows(","setHiddenApiExemptions","setAccessible(","takeScreenshot","dumpWindowHierarchy","Log.","printStackTrace","ACTION_SCROLL","ACTION_SET_TEXT"})assertFalse(x,s.contains(x));}
 @Test public void secondFullWalkAndMetadataPrecedeSingleClick()throws Exception{String s=source();int command=s.indexOf("NativeRewardsEntryProtocol.validCommit");int second=s.indexOf("second=walkMode(ui,b,clean,parentMode,showMode)");int metadata=s.indexOf("Stage.HELPER_COMMIT");int click=s.indexOf("performAction(AccessibilityNodeInfo.ACTION_CLICK)");assertTrue(command<second&&second<metadata&&metadata<click);assertEquals(click,s.lastIndexOf("performAction(AccessibilityNodeInfo.ACTION_CLICK)"));assertTrue(s.contains("first.candidate().equals(second.candidate())"));assertTrue(s.contains("before.ready().sameEntrySource(after.ready())"));}
 @Test public void entireTreeDeterminesUniqueness()throws Exception{String s=source();assertTrue(s.contains("while(!queue.isEmpty())"));assertTrue(s.contains("if(candidates.size()!=1)"));assertTrue(s.contains("scheduled+count>512"));assertTrue(s.contains("item.depth()>=32"));assertTrue(s.contains("chars+length>32768"));}
 @Test public void eofAndDeadlineBeforeAction()throws Exception{String s=source();assertTrue(s.contains("while((n=System.in.read())!=-1)"));assertTrue(s.contains("while(!input.done){check(b.deadline())"));assertTrue(s.contains("check(b.deadline());attempted=true"));assertTrue(s.contains("input.failed=true"));}
 @Test public void cleanupFailuresAreExplicit()throws Exception{String s=source();assertTrue(s.contains("try{w.recycle();}catch(Throwable ignored){clean.clean=false;}"));assertTrue(s.contains("if(inputThread.isAlive())clean.clean=false"));assertTrue(s.contains("!metadata.knownClean()"));assertTrue(s.contains("NativeRewardsEntryProtocol.Cleanup.UNKNOWN"));}
 @Test public void finalBlockingWindowCheckCannotOutliveEvidence()throws Exception{String s=source();int window=s.indexOf("verifyActiveWindow(second.candidate(),second.windowId(),clean)");int source=s.indexOf("if(!after.ready().fresh(SystemClock.elapsedRealtime()))",window);int tree=s.indexOf("if(!freshTree(second))",source);int dispatch=s.indexOf("check(b.deadline());attempted=true",tree);assertTrue(window>=0&&source>window&&tree>source&&dispatch>tree);String local=s.substring(source,dispatch);assertFalse(local.contains("metadata.read("));assertFalse(local.contains("refresh()"));assertFalse(local.contains("getWindow()"));}
 @Test public void modeIsExplicitLiteralAndLegacyDefault(){assertTrue(NativeRewardsEntryHelper.validModeArguments(new String[10]));String[] a=new String[11];a[10]="PARENT_REWARDS_V48";assertTrue(NativeRewardsEntryHelper.validModeArguments(a));a[10]="PARENT_REWARDS_V48 ";assertFalse(NativeRewardsEntryHelper.validModeArguments(a));assertFalse(NativeRewardsEntryHelper.validModeArguments(new String[12]));assertFalse(NativeRewardsEntryHelper.validModeArguments(null));}
 @Test public void semanticLabelIsExact(){assertTrue(NativeRewardsEntryHelper.semanticLabel("com.microsoft.bing","Rewards"));assertFalse(NativeRewardsEntryHelper.semanticLabel("other","Rewards"));assertFalse(NativeRewardsEntryHelper.semanticLabel("com.microsoft.bing","Rewards "));assertFalse(NativeRewardsEntryHelper.semanticLabel("com.microsoft.bing","rewards"));assertFalse(NativeRewardsEntryHelper.semanticLabel("com.microsoft.bing",null));}
 @Test public void onlyNonClickableChildClickableParentSameBounds(){assertTrue(NativeRewardsEntryHelper.pairFlags(true,true,false,true,true,true,true));assertFalse(NativeRewardsEntryHelper.pairFlags(false,true,false,true,true,true,true));assertFalse(NativeRewardsEntryHelper.pairFlags(true,false,false,true,true,true,true));assertFalse(NativeRewardsEntryHelper.pairFlags(true,true,true,true,true,true,true));assertFalse(NativeRewardsEntryHelper.pairFlags(true,true,false,false,true,true,true));assertFalse(NativeRewardsEntryHelper.pairFlags(true,true,false,true,false,true,true));assertFalse(NativeRewardsEntryHelper.pairFlags(true,true,false,true,true,false,true));assertFalse(NativeRewardsEntryHelper.pairFlags(true,true,false,true,true,true,false));}
 @Test public void v48FullSemanticCountPrecedesParentCompatibility()throws Exception{String s=source();int walk=s.indexOf("private static Tree walkParent(");String body=s.substring(walk,s.indexOf("private static Tree walk(UiAutomation",walk));assertTrue(body.contains("while(!queue.isEmpty())"));assertTrue(body.indexOf("semanticCount++")<body.indexOf("parent=node.getParent()"));assertTrue(body.contains("if(semanticCount!=1||clickBounds==null"));assertFalse(body.contains("getViewIdResourceName"));}
 @Test public void v48KeepsBothIdentitiesAndImmediateRelation()throws Exception{String s=source();assertTrue(s.contains("!first.semantic().equals(second.semantic())"));assertTrue(s.contains("!first.clickBounds().equals(second.clickBounds())"));assertTrue(s.contains("actual=tree.semantic().getParent()"));assertTrue(s.contains("actual.equals(tree.candidate())"));assertTrue(s.contains("expected.equals(c)"));assertTrue(s.contains("c.equals(p)"));assertTrue(s.contains("recycleTree(first,clean)"));assertTrue(s.contains("recycleTree(second,clean)"));assertTrue(s.contains("clean.recycle(t.semantic())"));}
 @Test public void v46LegacySelectorRemainsDefault()throws Exception{String s=source();assertTrue(s.contains("return parentMode?walkParent(ui,b,clean):walk(ui,b,clean)"));assertTrue(s.contains("NativeRewardsEntryProtocol.eligible(n.getPackageName(),n.getViewIdResourceName(),n.getContentDescription(),n.isVisibleToUser(),n.isEnabled(),n.isClickable())"));assertTrue(s.contains("if(candidates.size()!=1)"));assertTrue(s.contains("parentMode?refreshParentPair(second,clean):selector(second.candidate())"));}
 @Test public void eitherTextOrDescriptionCountsForAmbiguity(){assertTrue(NativeRewardsEntryHelper.semanticMarker("com.microsoft.bing","Rewards",null));assertTrue(NativeRewardsEntryHelper.semanticMarker("com.microsoft.bing",null,"Rewards"));assertTrue(NativeRewardsEntryHelper.semanticMarker("com.microsoft.bing","Rewards","Rewards"));assertFalse(NativeRewardsEntryHelper.semanticMarker("com.microsoft.bing","Rewards "," rewards"));}
 @Test public void selectedPairFieldsMustBeAbsentNotWhitespace()throws Exception{assertTrue(NativeRewardsEntryHelper.emptyField(null));assertTrue(NativeRewardsEntryHelper.emptyField(""));assertFalse(NativeRewardsEntryHelper.emptyField(" "));assertFalse(NativeRewardsEntryHelper.emptyField("Rewards"));String s=source();assertTrue(s.contains("!emptyField(child.getText())"));assertTrue(s.contains("!emptyField(parent.getText())"));assertTrue(s.contains("!emptyField(parent.getContentDescription())"));assertTrue(s.contains("if(semanticMarker(node.getPackageName(),text,description))"));}
}
